// Every method generated by `#[bitfield]` and `#[bitenum]` that returns a value must be
// `#[must_use]`. Each discarded call below is expected to produce exactly one error.
#![deny(unused_must_use)]

use arbitrary_int::u2;
use bitbybit::{bitenum, bitfield};

#[bitenum(u2, exhaustive = true)]
enum Color {
    Red = 0,
    Green = 1,
    Blue = 2,
    Cyan = 3,
}

#[bitfield(u32, default = 0, introspect)]
struct Everything {
    #[bit(0, rw)]
    flag: bool,
    #[bit(4, rw, stride = 1)]
    row: [bool; 4],
    #[bits(10..=11, rw)]
    color: Color,
}

#[allow(deprecated)]
fn main() {
    let value = Everything::DEFAULT;

    Everything::new_with_raw_value(0);
    Everything::new();
    value.raw_value();

    value.flag();
    value.row(0);
    value.color();

    value.with_flag(true);
    value.with_row(0, true);

    Everything::flag_mask();
    Everything::row_mask(0);

    Everything::builder();
    Everything::builder().with_flag(true);
    Everything::builder()
        .with_flag(true)
        .with_row([true; 4])
        .with_color(Color::Red)
        .build();

    Color::Red.raw_value();
    Color::new_with_raw_value(u2::new(0));

    // Setters mutate in place and must stay usable as statements.
    let mut value = value;
    value.set_flag(true);
    value.set_row(0, true);
}
